/**
 * A message over a list (CHECKS.md §85; provisional, agent): [message], when there is one, stands above [list] and takes
 * at most half the height, scrolling inside it, so the list keeps the rest and every word and action stays reachable. It
 * is always composed, so an SbCallout(live = true) can be heard, and the focus in the list keeps its place. Down at the
 * end of a tall message goes to its first action. In a low place, under five rows, half of it holds neither: message and
 * list then scroll as one, the list at the whole height, so the message scrolls away and leaves the list all of it; a drag
 * up on the list takes the message away first, and a focus in the list when the message comes keeps its place, with the
 * message above it (CHECKS.md §94).
 */
@Composable
fun SbMessageOverList(message: (@Composable () -> Unit)?, modifier: Modifier = Modifier, list: @Composable () -> Unit) {
    val scroll = rememberScrollState()
    val minRow = SebaroTheme.tokens.size.targetTouch + SebaroTheme.tokens.space.s2
    BoxWithConstraints(modifier) {
        val low = message != null && constraints.hasBoundedHeight && maxHeight < minRow * 5
        val most = constraints.maxHeight
        val messageTall = remember { mutableIntStateOf(0) }
        var listFocused by remember { mutableStateOf(false) }
        // the list first in line for what a drag up on it would scroll, so the message goes before its rows
        val first = remember(scroll) {
            object : NestedScrollConnection {
                override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset =
                    if (available.y < 0f) Offset(0f, -scroll.dispatchRawDelta(-available.y)) else Offset.Zero
            }
        }
        LaunchedEffect(low, messageTall.intValue) {
            if (low && listFocused && messageTall.intValue > 0) scroll.scrollTo(messageTall.intValue)
        }
        Layout(
            content = {
                if (message != null) {
                    Box(
                        (if (low) {
                            Modifier
                        } else {
                            Modifier
                                .sbScrollMark(scroll, SebaroTheme.colors.borderStrong)
                                .sbScrollKeys(scroll)
                                .verticalScroll(scroll)
                        }).onSizeChanged { messageTall.intValue = if (low) it.height else 0 },
                    ) { message() }
                }
                Box(
                    (if (low) Modifier.nestedScroll(first) else Modifier)
                        .onFocusChanged { listFocused = it.hasFocus },
                ) { list() }
            },
            modifier = if (low) {
                Modifier
                    .sbScrollMark(
                        scroll,
                        SebaroTheme.colors.borderStrong,
                        unseen = { messageTall.intValue - scroll.value - scroll.viewportSize },
                    )
                    .sbScrollKeys(scroll)
                    .verticalScroll(scroll)
            } else {
                Modifier
            },
        ) { measurables, c ->
            val loose = c.copy(minWidth = 0, minHeight = 0)
            if (low) {
                val over = measurables.dropLast(1).map { it.measure(loose.copy(maxHeight = 32_000)) }
                val overHeight = over.sumOf { it.height }
                val below = measurables.last().measure(loose.copy(minHeight = most, maxHeight = most))
                layout(c.maxWidth, overHeight + most) {
                    over.forEach { it.placeRelative(0, 0) }
                    below.placeRelative(0, overHeight)
                }
            } else {
                val over = measurables.dropLast(1).map { it.measure(loose.copy(maxHeight = most / 2)) }
                val overHeight = over.sumOf { it.height }
                val below = measurables.last().measure(loose.copy(minHeight = most - overHeight, maxHeight = most - overHeight))
                layout(c.maxWidth, most) {
                    over.forEach { it.placeRelative(0, 0) }
                    below.placeRelative(0, overHeight)
                }
            }
        }
    }
}
